async function shareReport(){if(!testState.report)return toast('\u8BF7\u5148\u5B8C\u6210\u6D4B\u8BD5');var name='Hs_'+safeName(testState.site.name||testState.site.key)+'_\u6D4B\u8BD5\u62A5\u544A.txt',file=new File([testState.report],name,{type:'text/plain;charset=utf-8'});try{if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){await navigator.share({title:'Hs \u7AD9\u6E90\u6D4B\u8BD5\u62A5\u544A',text:testState.summary,files:[file]});toast('\u5DF2\u6253\u5F00 iOS \u5206\u4EAB\u754C\u9762')}else{downloadReport(file);toast('\u5F53\u524D\u73AF\u5883\u4E0D\u652F\u6301\u5206\u4EAB\uFF0C\u5DF2\u4E0B\u8F7D TXT')}}catch(e){if(e&&e.name==='AbortError')return;downloadReport(file);toast('\u5206\u4EAB\u4E0D\u53EF\u7528\uFF0C\u5DF2\u4E0B\u8F7D TXT')}}
        // ==================== iOS\uFF1A\u5BFC\u51FA\u5E76\u5206\u4EAB TXT \u2192 \u76F4\u63A5\u6D4F\u89C8\u5668\u4E0B\u8F7D ====================
        // \u539F\u903B\u8F91 navigator.share \u4F18\u5148\u3001\u5931\u8D25\u56DE\u843D blob \u4E0B\u8F7D\uFF1BiOS/WKWebView \u4E0B\u4E24\u8005\u90FD\u5E38\u6CA1\u53CD\u5E94\u3002
        // \u5B9E\u6D4B location.href = '/js/report/xxx.txt?download=1' \u80FD\u76F4\u63A5\u89E6\u53D1\u4E0B\u8F7D\u4E14\u9875\u9762\u4E0D\u8DF3\u8D70\uFF0C
